        S=round((-1+np.sqrt(1+4*s))/2*2)/2  # S(S+1)=s
        res.setdefault(S,[]).append(e)
    return {k:min(vv) for k,vv in res.items()}
print('free ion Dq=0', sect(0.0))
print('Dq=2000', sect(2000.))
